SELECT id, user_id, parent_id, name, icon, sort_order, created_at, updated_at
FROM folders WHERE user_id = #{userId}
ORDER BY sort_order ASC, created_at ASC

SELECT id, user_id, parent_id, name, icon, sort_order, created_at, updated_at
FROM folders WHERE user_id = #{userId} AND parent_id = #{parentId}
ORDER BY sort_order ASC, created_at ASC
